t.script:
const PRICING_RULES = {
    motorcycle: { name: 'Motorcycle Express', base: 3.0, per_km: 0.5, per_kg: 0.1, min: 4.0 },
    sedan: { name: 'Sedan Courier', base: 5.0, per_km: 0.8, per_kg: 0.12, min: 8.0 },
    van: { name: 'Delivery Van', base: 12.0, per_km: 1.5, per_kg: 0.18, min: 20.0 },
    truck_small: { name: 'Small Truck (3-Ton)', base: 20.0, per_km: 2.0, per_kg: 0.2, min: 35.0 },
    truck_medium: { name: 'Medium Truck (10-Ton)', base: 35.0, per_km: 2.8, per_kg: 0.22, min: 50.0 }
};

let currentDistance = 5.0;

function updatePriceCalculation() {
    const vehicle = document.getElementById('vehicle_category').value || 'motorcycle';
    const weight = parseFloat(document.getElementById('weight_kg').value) || 2.0;
    const rule = PRICING_RULES[vehicle] || PRICING_RULES.motorcycle;

    const base = rule.base;
    const kmFee = currentDistance * rule.per_km;
    const kgFee = weight * rule.per_kg;
    const subtotal = base + kmFee + kgFee;
    const total = Math.max(subtotal, rule.min);

    document.getElementById('display_distance').innerText = currentDistance.toFixed(1);
    document.getElementById('display_vehicle').innerText = rule.name.split(' ')[0];
    document.getElementById('calc_base').innerText = '$' + base.toFixed(2);
    document.getElementById('calc_dist_km').innerText = currentDistance.toFixed(1);
    document.getElementById('calc_rate_km').innerText = '$' + rule.per_km.toFixed(2);
    document.getElementById('calc_km_fee').innerText = '$' + kmFee.toFixed(2);
    document.getElementById('calc_weight_val').innerText = weight.toFixed(1);
    document.getElementById('calc_kg_fee').innerText = '$' + kgFee.toFixed(2);
    document.getElementById('calc_total').innerText = '$' + total.toFixed(2) + ' USD';
    document.getElementById('btn_total_display').innerText = '$' + total.toFixed(2);
}

function setWeight(val) {
    document.getElementById('weight_kg').value = val;
    document.querySelectorAll('.weight-chip').forEach(el => {
        if (parseFloat(el.innerText) === val) el.classList.add('active');
        else el.classList.remove('active');
    });
    updatePriceCalculation();
}

function updatePayMethodSelection() {
    const payNow = document.querySelector('input[name="payment_method"][value="pay_now"]').checked;
    const cardNow = document.getElementById('card_pay_now');
    const cardCod = document.getElementById('card_pay_cod');
    if (payNow) {
        cardNow.classList.add('selected');
        cardCod.classList.remove('selected');
    } else {
        cardNow.classList.remove('selected');
        cardCod.classList.add('selected');
    }
}

document.getElementById('vehicle_category').addEventListener('change', updatePriceCalculation);
document.getElementById('weight_kg').addEventListener('input', updatePriceCalculation);

// Leaflet Map Init
document.addEventListener('DOMContentLoaded', function() {
    const defaultLat = -17.824858;
    const defaultLng = 31.053028;

    const map = L.map('map').setView([defaultLat, defaultLng], 13);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '&copy; OpenStreetMap contributors'
    }).addTo(map);

    let pickupMarker = null;
    let deliveryMarker = null;
    let routeLine = null;

    function createPinIcon(letter, bgColor) {
        const svg = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 44" width="28" height="38">' +
            '<path d="M16 0C7.163 0 0 7.163 0 16c0 10.667 16 28 16 28s16-17.333 16-28C32 7.163 24.837 0 16 0z" fill="' + bgColor + '" stroke="#ffffff" stroke-width="2"/>' +
            '<circle cx="16" cy="15" r="7" fill="#ffffff"/>' +
            '<text x="16" y="19" font-family="Poppins, Arial, sans-serif" font-size="10" font-weight="bold" fill="' + bgColor + '" text-anchor="middle">' + letter + '</text>' +
            '</svg>';
        const parser = new DOMParser();
        const doc = parser.parseFromString(svg, 'image/svg+xml');
        return L.divIcon({
            html: doc.documentElement.outerHTML,
            className: 'custom-pin-marker',
            iconSize: [28, 38],
            iconAnchor: [14, 38],
            popupAnchor: [0, -35]
        });
    }

    const pickupIcon = createPinIcon('A', '#2563EB');
    const deliveryIcon = createPinIcon('B', '#3db64c');

    function calculateDistance(lat1, lon1, lat2, lon2) {
        const R = 6371;
        const dLat = (lat2 - lat1) * Math.PI / 180;
        const dLon = (lon2 - lon1) * Math.PI / 180;
        const a = Math.sin(dLat/2) * Math.sin(dLat/2) +
                  Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
                  Math.sin(dLon/2) * Math.sin(dLon/2);
        const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
        return (R * c).toFixed(1);
    }

    function updateRouteAndDistance() {
        if (pickupMarker && deliveryMarker) {
            const pLatLng = pickupMarker.getLatLng();
            const dLatLng = deliveryMarker.getLatLng();
            const dist = calculateDistance(pLatLng.lat, pLatLng.lng, dLatLng.lat, dLatLng.lng);
            currentDistance = Math.max(parseFloat(dist), 1.0);
            document.getElementById('distance_km').value = currentDistance.toFixed(1);

            if (routeLine) map.removeLayer(routeLine);
            routeLine = L.polyline([pLatLng, dLatLng], {
                color: '#3db64c',
                weight: 4,
                dashArray: '8, 8',
                opacity: 0.85
            }).addTo(map);

            map.fitBounds([pLatLng, dLatLng], {padding: [50, 50]});
            document.getElementById('mapInstruction').innerHTML = '<i class="fa fa-check text-success me-1"></i> Route calculated (' + currentDistance.toFixed(1) + ' km)';
            updatePriceCalculation();
        }
    }

    function reverseGeocode(lat, lng, targetInputId, label) {
        fetch('https://nominatim.openstreetmap.org/reverse?format=json&lat=' + lat + '&lon=' + lng)
            .then(res => res.json())
            .then(data => {
                if (data && data.display_name) {
                    document.getElementById(targetInputId).value = data.display_name.split(',').slice(0, 3).join(',');
                }
            })
            .catch(() => {});
    }

    map.on('click', function(e) {
        const lat = e.latlng.lat;
        const lng = e.latlng.lng;

        if (!pickupMarker) {
            pickupMarker = L.marker([lat, lng], {icon: pickupIcon, draggable: true}).addTo(map);
            pickupMarker.bindPopup('<strong>Pickup (A)</strong><br/>' + lat.toFixed(5) + ', ' + lng.toFixed(5)).openPopup();
            document.getElementById('pickup_lat').value = lat;
            document.getElementById('pickup_lng').value = lng;
            reverseGeocode(lat, lng, 'pickup_address', 'Pickup');

            pickupMarker.on('dragend', function(ev) {
                const newPos = ev.target.getLatLng();
                document.getElementById('pickup_lat').value = newPos.lat;
                document.getElementById('pickup_lng').value = newPos.lng;
                reverseGeocode(newPos.lat, newPos.lng, 'pickup_address', 'Pickup');
                updateRouteAndDistance();
            });

            document.getElementById('mapInstruction').innerHTML = '<i class="fa fa-hand-pointer-o text-success me-1"></i> Click map to drop Green Delivery Pin (B)';
        } else if (!deliveryMarker) {
            deliveryMarker = L.marker([lat, lng], {icon: deliveryIcon, draggable: true}).addTo(map);
            deliveryMarker.bindPopup('<strong>Delivery (B)</strong><br/>' + lat.toFixed(5) + ', ' + lng.toFixed(5)).openPopup();
            document.getElementById('delivery_lat').value = lat;
            document.getElementById('delivery_lng').value = lng;
            reverseGeocode(lat, lng, 'delivery_address', 'Delivery');

            deliveryMarker.on('dragend', function(ev) {
                const newPos = ev.target.getLatLng();
                document.getElementById('delivery_lat').value = newPos.lat;
                document.getElementById('delivery_lng').value = newPos.lng;
                reverseGeocode(newPos.lat, newPos.lng, 'delivery_address', 'Delivery');
                updateRouteAndDistance();
            });

            updateRouteAndDistance();
        }
    });

    // Reset Button
    document.getElementById('resetMapBtn').addEventListener('click', function() {
        if (pickupMarker) { map.removeLayer(pickupMarker); pickupMarker = null; }
        if (deliveryMarker) { map.removeLayer(deliveryMarker); deliveryMarker = null; }
        if (routeLine) { map.removeLayer(routeLine); routeLine = null; }

        document.getElementById('pickup_lat').value = '';
        document.getElementById('pickup_lng').value = '';
        document.getElementById('delivery_lat').value = '';
        document.getElementById('delivery_lng').value = '';
        document.getElementById('mapInstruction').innerHTML = '<i class="fa fa-hand-pointer-o text-primary me-1"></i> Click map to drop Pickup Pin (A)';
    });

    updatePriceCalculation();
});

// Handle Form Submission
document.getElementById('zconnectBookingForm').addEventListener('submit', function(e) {
    e.preventDefault();
    const btn = document.getElementById('bookShipmentBtn');
    btn.disabled = true;
    btn.innerHTML = '<i class="fa fa-spinner fa-spin me-1"></i> Processing Booking...';

    const pickup = document.getElementById('pickup_address').value;
    const delivery = document.getElementById('delivery_address').value;
    const vehicle = document.getElementById('vehicle_category').value;
    const category = document.getElementById('shipment_category').value;
    const weight = parseFloat(document.getElementById('weight_kg').value) || 2.0;
    const distance = currentDistance;
    const senderName = document.getElementById('pickup_contact_name').value;
    const senderPhone = document.getElementById('pickup_phone').value;
    const receiverName = document.getElementById('delivery_contact_name').value;
    const receiverPhone = document.getElementById('delivery_phone').value;
    const payMethod = document.querySelector('input[name="payment_method"]:checked').value;

    fetch('/jsonrpc', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            jsonrpc: '2.0',
            method: 'call',
            params: {
                service: 'object',
                method: 'execute_kw',
                args: ['odoo_enterprise', 2, 'admin', 'zconnect.shipment', 'create', [{
                    'pickup_address': pickup,
                    'delivery_address': delivery,
                    'vehicle_category': vehicle,
                    'shipment_category': category,
                    'weight_kg': weight,
                    'distance_km': distance,
                    'pickup_contact_name': senderName,
                    'pickup_phone': senderPhone,
                    'delivery_contact_name': receiverName,
                    'delivery_phone': receiverPhone,
                    'customer_id': 3,
                    'state': (payMethod === 'pay_now') ? 'awaiting_payment' : 'confirmed',
                    'payment_state': (payMethod === 'pay_now') ? 'pending' : 'unpaid'
                }]]
            }
        })
    })
    .then(res => res.json())
    .then(data => {
        if (data.result) {
            const shipmentId = data.result;
            fetch('/jsonrpc', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    jsonrpc: '2.0',
                    method: 'call',
                    params: {
                        service: 'object',
                        method: 'execute_kw',
                        args: ['odoo_enterprise', 2, 'admin', 'zconnect.shipment', 'action_calculate_quote', [[shipmentId]]]
                    }
                })
            }).then(() => {
                if (payMethod === 'pay_now') {
                    window.location.href = '/shipment/pay?id=' + shipmentId;
                } else {
                    window.location.href = '/my/shipments/' + shipmentId;
                }
            }).catch(() => {
                if (payMethod === 'pay_now') {
                    window.location.href = '/shipment/pay?id=' + shipmentId;
                } else {
                    window.location.href = '/my/shipments/' + shipmentId;
                }
            });
        } else {
            window.location.href = '/my/shipments';
        }
    })
    .catch(() => {
        window.location.href = '/my/shipments';
    });
});

function processPayment(methodName) {
    const shipmentId = parseInt("");
    const txnRef = 'TXN-ZC-' + Math.floor(100000 + Math.random() * 900000);

    const mainContainer = document.getElementById('paymentMainContainer');
    const successScreen = document.getElementById('paymentSuccessScreen');

    fetch('/jsonrpc', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            jsonrpc: '2.0',
            method: 'call',
            params: {
                service: 'object',
                method: 'execute_kw',
                args: ['odoo_enterprise', 2, 'admin', 'zconnect.shipment', 'write', [[shipmentId], {
                    'payment_state': 'paid',
                    'state': 'confirmed'
                }]]
            }
        })
    }).then(() => {
        document.getElementById('receiptTxnId').innerText = txnRef;
        document.getElementById('receiptMethod').innerText = methodName;
        document.getElementById('receiptAmount').innerText = document.getElementById('payAmountDisplay').innerText;
        mainContainer.style.display = 'none';
        successScreen.style.display = 'block';
    }).catch(() => {
        document.getElementById('receiptTxnId').innerText = txnRef;
        document.getElementById('receiptMethod').innerText = methodName;
        mainContainer.style.display = 'none';
        successScreen.style.display = 'block';
    });
}
